/* gatef_core.h - shared driver of the gate-F CRT differential test (included by ref.c and cand.c).
 *
 * Corpus lines (generated by compare.py), one case per line, numbers in hex where they are bit patterns:
 *   pow <x bits> <y bits>          _CIpow (x in st(1), y in st(0))
 *   fmod <x bits> <y bits>         _CIfmod
 *   isnan <bits>                   _isnan
 *   atof <string as hex bytes>     atof
 *   toupper <int>                  toupper
 *   strchr <string hex> <int>      strchr: offset of the result, or -1 for NULL
 *   stricmp <string hex> <string hex>
 *   atoi <string hex>
 *   qsort <n> <width> <keys> <mode> <seed>
 *       n elements of `width` bytes: a key (int32, PRNG modulo `keys`) and a unique id (int32), rest zero.
 *       mode 0 compares keys ascending, 1 descending, 2 answers from a PRNG (an inconsistent comparator: only
 *       an identical algorithm makes the same calls). Result: number of comparator calls, FNV-1a hash of the
 *       call sequence (element indices of both arguments), hash of the final id order, and the ids (n <= 40).
 * Each side writes "<line number> <result>" per case; compare.py diffs the two files.
 *
 * The including side defines: Ptr (uint32_t test addresses), H(p) (host pointer), arena_reset, side_str, side_pow,
 * side_atof, side_isnan, side_toupper, side_strchr, side_stricmp, side_atoi, side_qsort; and calls qs_compare
 * from its comparator. */
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static void arena_reset(void);                                         /* frees the previous case's test memory */
static Ptr side_str(const uint8_t* s, size_t n);                       /* NUL-terminated copy in test memory */
static void side_pow(int fmod_, uint64_t x, uint64_t y, char* out);   /* writes the result description */
static uint64_t side_atof(Ptr s);
static int32_t side_isnan(uint64_t bits);
static int32_t side_toupper(int32_t ch);
static Ptr side_strchr(Ptr s, int32_t ch);
static int32_t side_stricmp(Ptr a, Ptr b);
static int32_t side_atoi(Ptr s);
static void side_qsort(Ptr base, uint32_t n, uint32_t width);

/* ---------------------------------------------------------------- qsort comparator (shared logic) */
static Ptr qs_base;
static uint32_t qs_width, qs_mode, qs_rng, qs_calls;
static uint64_t qs_hash;

static uint32_t lcg(uint32_t* s) {
    *s = *s * 1103515245u + 12345u;
    return *s >> 8;
}
static void fnv(uint64_t* h, uint32_t v) {
    int k;
    for (k = 0; k < 4; k++) {
        *h ^= (v >> (8 * k)) & 0xFF;
        *h *= 1099511628211ull;
    }
}

static int32_t qs_compare(Ptr a, Ptr b) {
    int32_t ka, kb, r;
    uint32_t ia = (a - qs_base) / qs_width, ib = (b - qs_base) / qs_width;
    memcpy(&ka, H(a), 4);
    memcpy(&kb, H(b), 4);
    qs_calls++;
    fnv(&qs_hash, ia);
    fnv(&qs_hash, ib);
    if (qs_mode == 0)
        r = ka < kb ? -1 : ka > kb;
    else if (qs_mode == 1)
        r = kb < ka ? -1 : kb > ka;
    else
        r = (int32_t)(lcg(&qs_rng) % 3u) - 1;
    return r;
}

/* ---------------------------------------------------------------- corpus */
static size_t unhex(const char* s, uint8_t* out, size_t cap) {
    size_t n = 0;
    if (!strcmp(s, "-"))
        return 0;                   /* the empty string */
    while (s[0] && s[1] && n < cap) {
        unsigned v;
        sscanf(s, "%2x", &v);
        out[n++] = (uint8_t)v;
        s += 2;
    }
    return n;
}

static void run_corpus(const char* corpus, const char* results) {
    FILE* in = fopen(corpus, "r");
    FILE* out = fopen(results, "w");
    static char line[70000], a1[33000], a2[33000];
    static uint8_t b1[16500], b2[16500];
    char res[512], op[16];
    long no = 0;
    if (!in || !out) {
        fprintf(stderr, "cannot open corpus or results\n");
        exit(2);
    }
    while (fgets(line, sizeof line, in)) {
        no++;
        arena_reset();
        a1[0] = a2[0] = 0;
        if (sscanf(line, "%15s %32999s %32999s", op, a1, a2) < 1)
            continue;
        res[0] = 0;
        if (!strcmp(op, "pow") || !strcmp(op, "fmod")) {
            uint64_t x = strtoull(a1, NULL, 16), y = strtoull(a2, NULL, 16);
            side_pow(op[0] == 'f', x, y, res);
        } else if (!strcmp(op, "isnan")) {
            sprintf(res, "%d", side_isnan(strtoull(a1, NULL, 16)));
        } else if (!strcmp(op, "atof")) {
            size_t n = unhex(a1, b1, sizeof b1);
            sprintf(res, "%016llx", (unsigned long long)side_atof(side_str(b1, n)));
        } else if (!strcmp(op, "toupper")) {
            sprintf(res, "%d", side_toupper((int32_t)strtol(a1, NULL, 10)));
        } else if (!strcmp(op, "strchr")) {
            size_t n = unhex(a1, b1, sizeof b1);
            Ptr s = side_str(b1, n), r = side_strchr(s, (int32_t)strtol(a2, NULL, 10));
            sprintf(res, "%ld", r ? (long)(r - s) : -1L);
        } else if (!strcmp(op, "stricmp")) {
            size_t n1 = unhex(a1, b1, sizeof b1), n2 = unhex(a2, b2, sizeof b2);
            sprintf(res, "%d", side_stricmp(side_str(b1, n1), side_str(b2, n2)));
        } else if (!strcmp(op, "atoi")) {
            size_t n = unhex(a1, b1, sizeof b1);
            sprintf(res, "%d", side_atoi(side_str(b1, n)));
        } else if (!strcmp(op, "qsort")) {
            uint32_t n, width, keys, mode, seed, i, ids_hash_dummy = 0;
            uint64_t order = 14695981039346656037ull;
            uint8_t* tmp;
            Ptr base;
            char* p = res;
            (void)ids_hash_dummy;
            sscanf(line + 6, "%u %u %u %u %u", &n, &width, &keys, &mode, &seed);
            tmp = (uint8_t*)calloc((size_t)n * width + 1, 1);
            for (i = 0; i < n; i++) {
                int32_t key = (int32_t)(lcg(&seed) % keys), id = (int32_t)i;
                memcpy(tmp + (size_t)i * width, &key, 4);
                memcpy(tmp + (size_t)i * width + 4, &id, 4);
            }
            base = side_str(tmp, (size_t)n * width);
            free(tmp);
            qs_base = base;
            qs_width = width;
            qs_mode = mode;
            qs_rng = seed ^ 0x5A5A5A5Au;
            qs_calls = 0;
            qs_hash = 14695981039346656037ull;
            side_qsort(base, n, width);
            for (i = 0; i < n; i++) {
                int32_t id;
                memcpy(&id, (uint8_t*)H(base) + (size_t)i * width + 4, 4);
                fnv(&order, (uint32_t)id);
            }
            p += sprintf(p, "calls %u seq %016llx order %016llx", qs_calls, (unsigned long long)qs_hash,
                         (unsigned long long)order);
            if (n <= 40) {
                p += sprintf(p, " ids");
                for (i = 0; i < n; i++) {
                    int32_t id;
                    memcpy(&id, (uint8_t*)H(base) + (size_t)i * width + 4, 4);
                    p += sprintf(p, " %d", id);
                }
            }
        } else {
            sprintf(res, "unknown-op");
        }
        fprintf(out, "%ld %s\n", no, res);
    }
    fclose(in);
    fclose(out);
}
